export const LIVE_RANGES = ["24h", "7d"] as const satisfies readonly LiveRange[];
export function parseLiveRange(v: string | null): LiveRange | null {
  const r = v ?? "7d";
  return (LIVE_RANGES as readonly string[]).includes(r) ? (r as LiveRange) : null;
}

